// The AI summary is HTML copied out of Google's widget (see AskAiPanel), which
// is generated by a model and rendered by a third party. Before it goes into
// the page it is rebuilt from an allow-list: only the tags a summary needs
// survive, every attribute but a link's href is dropped, and links are
// reduced to plain http(s) URLs. Anything else (scripts, event handlers,
// javascript: links, styles, embeds) never reaches the page.
//
// Parsing with DOMParser is inert: scripts don't run and handlers don't fire
// while the markup is only being inspected.

const ALLOWED_TAGS = new Set([
  'p', 'br', 'strong', 'b', 'em', 'i', 'code', 'pre', 'ul', 'ol', 'li',
  'a', 'blockquote', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
]);

// Removed together with everything inside them. Any other tag that isn't
// allowed (div, span, ...) is unwrapped: its text and allowed children stay.
const DROP_WITH_CONTENT = new Set([
  'script', 'style', 'iframe', 'frame', 'frameset', 'object', 'embed', 'applet',
  'svg', 'math', 'template', 'noscript', 'link', 'meta', 'base', 'form',
  'input', 'button', 'select', 'textarea', 'audio', 'video', 'source', 'canvas',
]);

/**
 * Turns a link target into a safe one, or null when the link should be
 * dropped (its text is kept). Links to this site become site-relative paths
 * under the current locale's baseUrl, so they can be followed without a page
 * load; everything else must be http(s).
 */
export function resolveLink(raw, {origin, siteOrigin, baseUrl}) {
  const href = (raw || '').trim();
  if (!href || href.startsWith('#')) return null;
  let url;
  try {
    url = new URL(href, `${origin}/`);
  } catch {
    return null;
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;

  const internal = url.origin === origin || url.origin === siteOrigin;
  if (!internal) return {href: url.href, internal: false};

  const base = baseUrl.replace(/\/$/, '');
  let path = url.pathname;
  if (!(path === base || path.startsWith(`${base}/`))) path = `${base}${path}`;
  return {href: `${path}${url.search}${url.hash}`, internal: true};
}

function copyInto(source, target, doc, ctx) {
  for (const node of Array.from(source.childNodes)) {
    if (node.nodeType === 3) {
      target.appendChild(doc.createTextNode(node.nodeValue));
      continue;
    }
    if (node.nodeType !== 1) continue; // comments, processing instructions

    const tag = node.tagName.toLowerCase();
    if (DROP_WITH_CONTENT.has(tag)) continue;

    if (!ALLOWED_TAGS.has(tag)) {
      copyInto(node, target, doc, ctx); // unwrap
      continue;
    }

    if (tag === 'a') {
      const link = resolveLink(node.getAttribute('href'), ctx);
      if (!link) {
        copyInto(node, target, doc, ctx);
        continue;
      }
      const a = doc.createElement('a');
      a.setAttribute('href', link.href);
      a.setAttribute('rel', 'noopener noreferrer');
      if (link.internal) a.setAttribute('data-ask-ai-internal', '');
      else a.setAttribute('target', '_blank');
      copyInto(node, a, doc, ctx);
      target.appendChild(a);
      continue;
    }

    const el = doc.createElement(tag); // no attributes carried over
    copyInto(node, el, doc, ctx);
    target.appendChild(el);
  }
}

/**
 * @param {string} html markup taken from the widget
 * @param {{origin: string, siteOrigin: string, baseUrl: string}} ctx
 *   origin: where the page is served from (window.location.origin);
 *   siteOrigin: the site's canonical origin (siteConfig.url);
 *   baseUrl: the current locale's base path (siteConfig.baseUrl)
 */
export function sanitizeSummary(html, ctx) {
  const parsed = new DOMParser().parseFromString(`<body>${html}</body>`, 'text/html');
  const out = parsed.implementation.createHTMLDocument('');
  const root = out.createElement('div');
  copyInto(parsed.body, root, out, {
    origin: ctx.origin,
    siteOrigin: new URL(ctx.siteOrigin).origin,
    baseUrl: ctx.baseUrl,
  });
  return root.innerHTML;
}
